    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Batailles.html&quot; title=&quot;Myst&#232;re des batailles&quot;&gt;Myst&#232;re des batailles&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Du-Bois.html&quot; title=&quot;Myst&#232;re du bois&quot;&gt;Myst&#232;re du bois&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Cieux.html&quot; title=&quot;Myst&#232;re des cieux&quot;&gt;Myst&#232;re des cieux&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Flammes.html&quot; title=&quot;Myst&#232;re des flammes&quot;&gt;Myst&#232;re des flammes&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-Lhiver.html&quot; title=&quot;Myst&#232;re de l&amp;#39;hiver&quot;&gt;Myst&#232;re de l&#39;hiver&lt;/a&gt; (PotN)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-Lintrigue.html&quot; title=&quot;Myst&#232;re de l&amp;#39;intrigue&quot;&gt;Myst&#232;re de l&#39;intrigue&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-La-Cicatrice-Magique.html&quot; title=&quot;Myst&#232;re de la cicatrice magique&quot;&gt;Myst&#232;re de la cicatrice magique&lt;/a&gt; (MMI)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-La-Lune.html&quot; title=&quot;Myst&#232;re de la lune&quot;&gt;Myst&#232;re de la lune&lt;/a&gt; (PFC)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Du-M&#233;tal.html&quot; title=&quot;Myst&#232;re du m&#233;tal&quot;&gt;Myst&#232;re du m&#233;tal&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-La-Nature.html&quot; title=&quot;Myst&#232;re de la nature&quot;&gt;Myst&#232;re de la nature&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-Locculte.html&quot; title=&quot;Myst&#232;re de l&amp;#39;occulte&quot;&gt;Myst&#232;re de l&#39;occulte&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Os.html&quot; title=&quot;Myst&#232;re des os&quot;&gt;Myst&#232;re des os&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Pierres.html&quot; title=&quot;Myst&#232;re des pierres&quot;&gt;Myst&#232;re des pierres&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Du-Savoir.html&quot; title=&quot;Myst&#232;re du savoir&quot;&gt;Myst&#232;re du savoir&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-La-Sombre-Tapisserie.html&quot; title=&quot;Myst&#232;re de la sombre tapisserie&quot;&gt;Myst&#232;re de la sombre tapisserie&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Du-Temps.html&quot; title=&quot;Myst&#232;re du temps&quot;&gt;Myst&#232;re du temps&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Failles-Ext&#233;rieures.html&quot; title=&quot;Myst&#232;re des failles ext&#233;rieures&quot;&gt;Myst&#232;re des failles ext&#233;rieures&lt;/a&gt; (MMI)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Vagues.html&quot; title=&quot;Myst&#232;re des vagues&quot;&gt;Myst&#232;re des vagues&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Du-Vent.html&quot; title=&quot;Myst&#232;re du vent&quot;&gt;Myst&#232;re du vent&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-La-Vie.html&quot; title=&quot;Myst&#232;re de la vie&quot;&gt;Myst&#232;re de la vie&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Volcans.html&quot; title=&quot;Myst&#232;re des volcans&quot;&gt;Myst&#232;re des volcans&lt;/a&gt; (AP95)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;b&gt;Comp&#233;tences de classe.&lt;/b&gt; Un oracle du myst&#232;re de la vie ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) et &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Sorts suppl&#233;mentaires.&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Des-Morts-Vivants.html&quot; title=&quot;D&#233;tection des morts-vivants&quot;&gt;D&#233;tection des morts-vivants&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Restauration-Partielle.html&quot; title=&quot;Restauration partielle&quot;&gt;restauration partielle&lt;/a&gt;&lt;/i&gt; (4), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Neutralisation-Du-Poison.html&quot; title=&quot;Neutralisation du poison&quot;&gt;neutralisation du poison&lt;/a&gt;&lt;/i&gt; (6), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Restauration.html&quot; title=&quot;Restauration&quot;&gt;restauration&lt;/a&gt;&lt;/i&gt; (8), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souffle-De-Vie.html&quot; title=&quot;Souffle de vie&quot;&gt;souffle de vie&lt;/a&gt;&lt;/i&gt; (10), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Supr&#234;me.html&quot; title=&quot;Gu&#233;rison supr&#234;me&quot;&gt;gu&#233;rison supr&#234;me&lt;/a&gt;&lt;/i&gt; (12), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Restauration-Supr&#234;me.html&quot; title=&quot;Restauration supr&#234;me&quot;&gt;restauration supr&#234;me&lt;/a&gt;&lt;/i&gt; (14), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Supr&#234;me-De-Groupe.html&quot; title=&quot;Gu&#233;rison supr&#234;me de groupe&quot;&gt;gu&#233;rison supr&#234;me de groupe&lt;/a&gt;&lt;/i&gt; (16), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;surrection-Supr&#234;me.html&quot; title=&quot;R&#233;surrection supr&#234;me&quot;&gt;r&#233;surrection supr&#234;me&lt;/a&gt;&lt;/i&gt; (18). &lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;R&#233;v&#233;lations&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;v&#233;lations_0&quot; href=&quot;#R&#233;v&#233;lations_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt; &lt;i&gt;Un oracle du myst&#232;re de la vie peut choisir l’une des r&#233;v&#233;lations suivantes.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Canalisation (Sur).&lt;/b&gt; L’oracle &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canalise&lt;/a&gt; l’&#233;nergie positive comme un &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; en utilisant son niveau d’oracle comme niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; effectif quand il d&#233;termine le montant de d&#233;g&#226;ts soign&#233;s (ou inflig&#233; &#224; des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants&lt;/a&gt;) et les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt;. Chaque jour, il peut utiliser ce pouvoir un nombre de fois &#233;gal &#224; 1 + modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Voir aussi les &lt;a class=&quot;pagelink&quot; href=&quot;Variantes-De-Canalisation.html&quot; title=&quot;Les variantes de canalisation du pr&#234;tre&quot;&gt;variantes de canalisation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html#33&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;→&lt;/a&gt; Oracle, Corps d&#39;&#233;nergie : Combien de fois par round puis-je utiliser cette capacit&#233; pour soigner quelqu&#39;un ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Le texte dit &#171; une fois par round &#187;. Que le personnage traverse l&#39;espace occup&#233; d&#39;un alli&#233; ou qu&#39;un alli&#233; traverse l&#39;espace occup&#233; par le personnage, le soin ne peut se d&#233;clencher qu&#39;une fois par round. &lt;i&gt;(Retour &#224; la &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-De-La-Vie.html&quot; title=&quot;Myst&#232;re de la vie&quot;&gt;capacit&#233;&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;b&gt;Corps d’&#233;nergie (Sur).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, l’oracle peut transformer son corps en &#233;nergie pure et ressemble alors &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#233;mentaire.html&quot; title=&quot;&#201;l&#233;mentaire&quot;&gt;&#233;l&#233;mentaire&lt;/a&gt; de feu d’un blanc dor&#233;. Sous cette forme, il devient de sous-type &lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#233;mentaire.html&quot; title=&quot;&#201;l&#233;mentaire&quot;&gt;&#233;l&#233;mentaire&lt;/a&gt; et d&#233;gage une lumi&#232;re chaude et accueillante qui augmente le degr&#233; de luminosit&#233; d’une cat&#233;gorie, jusqu’&#224; une lumi&#232;re normale. Tout mort-vivant qui le frappe avec une partie de son corps ou avec une arme tenue en main lui inflige des d&#233;g&#226;ts normaux mais re&#231;oit &#233;galement 1d6 points de d&#233;g&#226;ts d’&#233;nergie positive + 1 point par niveau d’oracle. Les cr&#233;atures qui manient des armes avec une allonge ne sont pas soumises &#224; ces d&#233;g&#226;ts si elles attaquent l’oracle. Si ce dernier entre en &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt; contre un mort-vivant ou l’attaque &#224; mains nues ou avec une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Attaquenaturelle.html&quot; title=&quot;arme naturelle&quot;&gt;arme naturelle&lt;/a&gt;, il peut lui infliger ce type de d&#233;g&#226;ts au lieu de ceux que devraient faire son attaque. Une fois par round, si l’oracle traverse une case occup&#233;e par une cr&#233;ature vivante alli&#233;e ou si un alli&#233; traverse la case de l’oracle, l’alli&#233; est gu&#233;ri de 1d6 points de d&#233;g&#226;ts + 1 par niveau d’oracle. Ce dernier peut utiliser ce pouvoir pour se soigner par une action de mouvement. Il choisit de soigner une cr&#233;ature ou non quand elle traverse sa case. Il peut reprendre sa forme normale par une action libre. Chaque jour, il peut rester sous forme d’&#233;nergie pendant un nombre de rounds &#233;gal &#224; son niveau d’oracle.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Gu&#233;rison s&#233;curis&#233;e (Sur).&lt;/b&gt; Quand l’oracle lance un sort qui rend des &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;points de vie&lt;/a&gt; &#224; la cible, il ne provoque pas d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt; lors de l’incantation.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Gu&#233;risseur combattant (Sur).&lt;/b&gt; Quand le personnage lance un sort de soins (qui comporte le mot &#171; soins &#187; dans son intitul&#233;), il peut le faire par une action rapide, comme s’il utilisait &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Rapide.html&quot; title=&quot;Incantation rapide&quot;&gt;Incantation rapide&lt;/a&gt;, &#224; condition de d&#233;penser deux emplacements de sort. Il peut utiliser ce pouvoir une fois par jour au niveau 7 et une fois de plus tous les quatre niveaux qui suivent. Il doit &#234;tre au moins de niveau 7 pour choisir cette r&#233;v&#233;lation.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Lien vital (Sur).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, l’oracle peut cr&#233;er un lien entre sa personne et une autre cr&#233;ature. &#192; chaque round, au d&#233;but de son tour, si la cr&#233;ature li&#233;e a perdu 5 points de vie ou plus par rapport &#224; son maximum, elle gu&#233;rit de 5 points de vie et l’oracle en perd 5. L’oracle peut activer un lien de ce type par niveau de classe. Le lien persiste jusqu’&#224; ce que la cr&#233;ature li&#233;e meure, que l’oracle meure, que la distance qui les s&#233;pare d&#233;passe la port&#233;e moyenne (30 m + 3 m/niveau) (20 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt; + 2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;/niveau) ou que le personnage le rompe par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt; (s’il poss&#232;de plusieurs liens, il peut en briser autant qu’il veut lors de la m&#234;me &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Mains gu&#233;risseuses (Ext).&lt;/b&gt; L’oracle gagne un bonus de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;. Il peut administrer les premiers soins &#224; deux personnes &#224; la fois ou les traiter contre le &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;poison&quot;&gt;poison&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; (en faisant un test de &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; pour chacune). Quand il utilise cette comp&#233;tence pour soigner les blessures dues &#224; une chausse-trappe (etc.), pour traiter des blessures mortelles, du poison, des maladies ou pour prodiguer des soins &#224; long terme, il peut soigner deux fois plus de gens qu’une personne ordinaire. Il peut s’administrer lui-m&#234;me des soins &#224; long terme.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Perception de la vie (Sur).&lt;/b&gt; L’oracle per&#231;oit et localise toute cr&#233;ature vivante situ&#233;e dans les 9 m&#232;tres (6 cases) , comme s’il poss&#233;dait le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Aveugle-(Capacit&#233;).html&quot; title=&quot;vision aveugle&quot;&gt;vision aveugle&lt;/a&gt;. Il doit &#234;tre de niveau 11 au minimum pour avoir cette r&#233;v&#233;lation.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Retardement de l’affliction (Sur).&lt;/b&gt; Une fois par jour, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;, quand l’oracle rate un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; contre une &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;maladie&quot;&gt;maladie&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;poison&quot;&gt;poison&lt;/a&gt;, il peut en ignorer les effets pendant 1 heure par niveau. Aux niveaux 7 et 15, il peut utiliser ce pouvoir une fois de plus par jour.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Soins am&#233;lior&#233;s (Sur).&lt;/b&gt; Quand l’oracle lance un sort de soins, il base le maximum de points de vie rendus sur son niveau d’oracle et non sur la limite bas&#233;e sur le sort. Par exemple, un oracle de la vie de niveau 11 qui a eu cette r&#233;v&#233;lation lance &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt; pour soigner 1d8+11 points de vie et non 1d8+5 au maximum.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Stimulant spirituel (Sur).&lt;/b&gt; Quand l’oracle lance un sort qui remonte la vie de la cible au maximum, tout point en exc&#232;s persiste pendant un round par niveau sous forme de &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort#Pvtemporaires.html&quot; title=&quot;point de vie temporaire&quot;&gt;point de vie temporaire&lt;/a&gt; (avec un maximum de points &#233;gal au niveau de l’oracle).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#233;v&#233;lation finale.&lt;/b&gt; Quand l’oracle atteint le niveau 20, il devient un conduit parfait pour la &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canalisation&lt;/a&gt; d’&#233;nergie vitale. Il est immunis&#233; contre le &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Saignement.html&quot; title=&quot;Saignement&quot;&gt;saignement&lt;/a&gt;, les attaques de &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Mort.html&quot; title=&quot;Mort&quot;&gt;mort&lt;/a&gt;, l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puisement&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Fatigue.html&quot; title=&quot;Fatigue&quot;&gt;fatigue&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;e&lt;/a&gt;, les niveaux n&#233;gatifs et la condition &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuse&lt;/a&gt;. Les absorptions et les &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissements temporaires de caract&#233;ristique&lt;/a&gt; ne peuvent pas r&#233;duire une valeur &#224; moins de 1. L’oracle r&#233;ussit automatiquement tous ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#DEG&#194;TSEXCESSIFS&quot; title=&quot;Blessures et mort&quot;&gt;d&#233;g&#226;ts excessifs&lt;/a&gt;. Quand l’oracle se trouve en dessous de 0 point de vie, il ne meurt pas tant que son total de points n&#233;gatifs n’est pas &#233;gal &#224; deux fois sa valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;.
